// Standalone page — does not affect the live homepage at /.
'use client';
import { useState, useCallback } from 'react';
import Link from 'next/link';
import {
  ArrowRight, ArrowUp, Brain, Zap, Fingerprint, Heart, Sparkles,
  Shield, Check, X, Star, Quote, User, Loader2,
} from 'lucide-react';
import SoulPrintLogo from '@/components/SoulPrintLogo';

const FIVE_FEATURES = [
  {
    icon: Brain,
    title: 'Persistent Memory',
    desc: 'Remembers your history, preferences & projects — forever.',
    iconColor: 'text-orange-400',
  },
  {
    icon: Zap,
    title: 'Dynamic Intelligence',
    desc: 'Auto-picks the best AI model for each task.',
    iconColor: 'text-yellow-400',
  },
  {
    icon: Fingerprint,
    title: 'Identity Alignment',
    desc: 'Learns your decision style & communication cadence.',
    iconColor: 'text-purple-400',
  },
  {
    icon: Heart,
    title: 'Relationship Layer',
    desc: 'Gets smarter the more you use it; truly grows with you.',
