// as base64 chunks — no manual resampling needed since the native layer records at this rate
// directly (unlike the web version, which has to downsample AudioContext's rate).
//
// react-native-live-audio-stream is a third-party native module, so it is NOT compiled into
// Expo Go — only into a dev client / custom build. Worse, its module scope runs
// `new NativeEventEmitter(RNLiveAudioStream)` with an undefined native module under Expo Go,
// which throws on import and would take down the whole app at startup. So it is required
// lazily behind a try/catch and callers check isMicCaptureAvailable() first; in Expo Go the
// rest of the app (auth, chat, imprints, memory) still runs, and only the voice screen is
// gated off.
import { INPUT_SAMPLE_RATE } from './geminiLiveClient';

// The library's .d.ts declares `on()` as returning void, but the implementation returns an
// EventEmitter subscription (react-native-live-audio-stream/index.js) — cast to use it.
type Unsubscribable = { remove: () => void };

interface LiveAudioStreamModule {
  init: (options: Record<string, unknown>) => void;
  start: () => void;
  stop: () => void;
  on: (event: 'data', cb: (data: string) => void) => unknown;
}

let dataSubscription: Unsubscribable | null = null;
let cachedModule: LiveAudioStreamModule | null | undefined;

function loadLiveAudioStream(): LiveAudioStreamModule | null {
  if (cachedModule !== undefined) return cachedModule;
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const mod = require('react-native-live-audio-stream');
    cachedModule = (mod?.default ?? mod) as LiveAudioStreamModule;
  } catch {
    cachedModule = null;
  }
  return cachedModule;
}

/** False under Expo Go, where the native mic module isn't available. */
export function isMicCaptureAvailable(): boolean {
  return loadLiveAudioStream() !== null;
}

export function startMicCapture(onChunk: (base64Pcm16: string) => void) {
  const LiveAudioStream = loadLiveAudioStream();
  if (!LiveAudioStream) {
    throw new Error(
      'Live voice requires a development build — the native microphone module is not available in Expo Go.'
    );
  }

  LiveAudioStream.init({
    sampleRate: INPUT_SAMPLE_RATE,
    channels: 1,
    bitsPerSample: 16,
    audioSource: 6, // VOICE_RECOGNITION on Android; ignored on iOS
    bufferSize: 4096,
    wavFile: '', // streaming mode, no file output
  });

  dataSubscription = LiveAudioStream.on('data', onChunk) as unknown as Unsubscribable;
  LiveAudioStream.start();
}

export function stopMicCapture() {
  const LiveAudioStream = loadLiveAudioStream();
  if (!LiveAudioStream) return;

  LiveAudioStream.stop();
  dataSubscription?.remove();
  dataSubscription = null;
}
