const BACKEND_URL =
  (typeof process !== 'undefined' && (process.env as any).REACT_APP_BACKEND_URL) || '';

export const generateScoutingReport = async (params: SearchParams): Promise<ParsedReport> => {
  let response: Response;
  try {
    response = await fetch(`${BACKEND_URL}/api/scouting/generate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
    });
  } catch (err) {
    console.error('Network error contacting scouting backend:', err);
    throw new Error('Network error. Please check your connection and try again.');
  }

  if (!response.ok) {
    let detail = `HTTP ${response.status}`;
    try {
      const err = await response.json();
      if (err?.detail) detail = err.detail;
    } catch { /* ignore parse error */ }
    console.error('Scouting backend error:', detail);
    throw new Error(detail);
  }

  const payload = await response.json() as { text: string; sources: Array<{ title?: string; uri: string }> };
  const text = payload.text || 'No report generated.';
  const sources = (payload.sources || []).map(s => ({
    title: s.title || s.uri,
    uri: s.uri,
  }));

  // Regex Parsing (mirrors original client-side logic)
  const teamMatch = text.match(/TEAM:\s*(.+)/i);
  const locationMatch = text.match(/LOCATION:\s*(.+)/i);
  const seasonMatch = text.match(/SEASON:\s*(.+)/i);
  const recordMatch = text.match(/RECORD:\s*([\d]+-[\d]+)/i);
  const urlMatch = text.match(/MAXPREPS_URL:\s*(http.+)/i);
  const videoMatch = text.match(/VIDEO_LINKS:\s*(.+)/i);

  const parseSection = (header: string, nextHeader: string | null) => {
    const start = text.indexOf(header);
    if (start === -1) return 'Section not found.';
    const contentStart = start + header.length;
    const end = nextHeader ? text.indexOf(nextHeader, contentStart) : text.length;
    return text.slice(contentStart, end === -1 ? text.length : end).trim();
  };

  let videoLinks: string[] = [];
  if (videoMatch && videoMatch[1] && !videoMatch[1].includes('None')) {
    videoLinks = videoMatch[1].split(',').map(l => l.trim()).filter(l => l.startsWith('http'));
  }

  return {
    teamName: teamMatch ? teamMatch[1].trim() : undefined,
    teamLocation: locationMatch ? locationMatch[1].trim() : undefined,
    teamSeason: seasonMatch ? seasonMatch[1].trim() : undefined,
    teamRecord: recordMatch ? recordMatch[1].trim() : undefined,
    maxPrepsUrl: urlMatch ? urlMatch[1].trim() : undefined,
    videoLinks,
    scoutingReport: parseSection('# SCOUTING REPORT', '# KEY PLAYERS'),
    keyPlayers: parseSection('# KEY PLAYERS', '# GAME PLAN'),
    gamePlan: parseSection('# GAME PLAN', '# TEAM CHEAT SHEET'),
    cheatSheet: parseSection('# TEAM CHEAT SHEET', '# PLAYER TIPS'),
    playerTips: parseSection('# PLAYER TIPS', null),
    rawText: text,
    sources,
  };
};
